/** A legal requirement a check enforces. */
export interface CheckRequirementRef {
  /** Requirement id in the legal catalog. */
  id: string;
  /** Jurisdiction. */
  jurisdiction: "US-FED" | "US-AL" | "US-AK" | "US-AZ" | "US-AR" | "US-CA" | "US-CO" | "US-CT" | "US-DE" | "US-DC" | "US-FL" | "US-GA" | "US-HI" | "US-ID" | "US-IL" | "US-IN" | "US-IA" | "US-KS" | "US-KY" | "US-LA" | "US-ME" | "US-MD" | "US-MA" | "US-MI" | "US-MN" | "US-MS" | "US-MO" | "US-MT" | "US-NE" | "US-NV" | "US-NH" | "US-NJ" | "US-NM" | "US-NY" | "US-NC" | "US-ND" | "US-OH" | "US-OK" | "US-OR" | "US-PA" | "US-RI" | "US-SC" | "US-SD" | "US-TN" | "US-TX" | "US-UT" | "US-VT" | "US-VA" | "US-WA" | "US-WV" | "US-WI" | "US-WY";
  /** Legal citation. */
  citation: string;
  /** Requirement title. */
  title: string;
  /** Official source. */
  source_url: string;
}

/** One engine check and its verdict. */
export interface CheckVerdict {
  /** Stable id of the check. */
  check_id: string;
  /** pass, fail, needs_review (a human or more data must decide) or not_applicable. */
  status: "pass" | "fail" | "needs_review" | "not_applicable";
  /** Severity. */
  severity: "critical" | "high" | "medium" | "low";
  /** What the check requires. */
  title: string;
  /** What the engine observed. */
  explanation: string;
  /** Confidence 0..1. */
  confidence: number;
  /** Requirements this check enforces under the requested jurisdictions. */
  requirements: Array<CheckRequirementRef>;
  /** How to fix a failing / unclear check. */
  fix?: string;
  /** Page checks on static HTML: the engine status on the estimated layout. */
  static_estimate?: "pass" | "fail" | "needs_review" | "not_applicable";
  evidence: VerdictEvidence;
  /** User-facing status. needs_fix (a requirement is clearly not met: `compliance.fix` is the one change), pending_live_check (everything Checkbox can see is right; the live event has not been observed yet — counts as passing the checks), verified_live (observed live: proof run, real BCC'd send, Stripe-confirmed cancellation), your_call (a real decision for a person: `compliance.question`), compliant (passes; grey areas carry a `compliance.note`), not_applicable, not_set_up (no sign the email or setting exists yet: `compliance.fix` is the one-click way to set it up; never counts as passing the checks), not_checked (Checkbox has not tried it yet, e.g. the cancel flow: `compliance.fix` says how; never counts as passing the checks). */
  compliance_status: "needs_fix" | "pending_live_check" | "verified_live" | "your_call" | "compliant" | "not_applicable" | "not_set_up" | "not_checked";
  compliance: ComplianceInfo;
}

/** Verdict per legal requirement. */
export type CheckRequirementVerdict = CheckRequirementRef & {
  /** Worst status among the requirement’s checks. */
  status: "pass" | "fail" | "needs_review" | "not_applicable";
  /** Checks that enforce it. */
  check_ids: Array<string>;
};

/** A note about the input (never a compliance verdict). */
export interface CheckWarning {
  /** Stable warning code. */
  code: string;
  /** Explanation. */
  message: string;
  /** Related parameter. */
  param?: string;
}

/** A suggested replacement that passes the checks, verified by the engine. */
export interface CheckReplacement {
  /** Disclosure generated from the plan terms that passes the checks (locked wording). */
  disclosure_text: string;
  /** The same terms as one short line, verified by the engine like disclosure_text (present only when it passes every targeted check); disclosure_text is then the fuller version. */
  short_disclosure_text?: string;
  /** Label for the unchecked, required consent checkbox. */
  consent_label: string;
  /** Purchase button label that itself states the renewal. */
  button_text: string;
  /** Drop-in markup: disclosure + unchecked required checkbox + button. When consent_on is set (the purchase completes on a Stripe Payment Link or Stripe Checkout), the terms only: no checkbox, no button. */
  html: string;
  /** Set when consent is collected on the Stripe-hosted page, not on this page: html is then the terms only. */
  consent_on?: "payment_link" | "stripe_checkout";
  /** What html contains and what is still needed elsewhere (set with consent_on). */
  note?: string;
  /** The same markup as JSX for React / Next.js components (className, htmlFor, style objects, self-closed inputs); the text is unchanged. */
  jsx?: string;
  /** Placeholders left to fill (e.g. {{cancel_url}}). */
  placeholders: Array<string>;
  /** The engine passes every targeted sign-up check on a page using this replacement. */
  verified: boolean;
  /** Targeted checks that still do not pass with it (normally empty). */
  remaining_checks: Array<string>;
  /** sha256 of disclosure + consent label. */
  sha256: string;
}

/** Verdict on a checkout disclosure plus a verified replacement. */
export interface DisclosureCheckResult {
  /** Id of this check run (chk_…). Checks are stateless and not stored. */
  id: string;
  /** String representing the object's type. Always "check_result". */
  object: "check_result";
  /** true for live-mode objects, false for test mode (ck_test_ keys act on an isolated sandbox). */
  livemode: boolean;
  /** When the check ran. Unix timestamp in seconds. */
  created: number;
  /** Which check ran. */
  kind: "disclosure" | "stripe_checkout_session" | "stripe_payment_link" | "email" | "page";
  /** Overall: fail if any check fails, else needs_review if any needs review, else pass (not_applicable when nothing applies). */
  verdict: "pass" | "fail" | "needs_review" | "not_applicable";
  /** Counts by status. */
  summary: {
    /** Checks passing. */
    pass: number;
    /** Checks failing. */
    fail: number;
    /** Checks needing review. */
    needs_review: number;
    /** Checks not applicable. */
    not_applicable: number;
  };
  /** Every evaluated check. */
  checks: Array<CheckVerdict>;
  /** Verdict per legal requirement (federal first, then by state). */
  requirements: Array<CheckRequirementVerdict>;
  /** Notes about the input. */
  warnings: Array<CheckWarning>;
  /** Jurisdictions evaluated. */
  jurisdictions: "all" | Array<"US-FED" | "US-AL" | "US-AK" | "US-AZ" | "US-AR" | "US-CA" | "US-CO" | "US-CT" | "US-DE" | "US-DC" | "US-FL" | "US-GA" | "US-HI" | "US-ID" | "US-IL" | "US-IN" | "US-IA" | "US-KS" | "US-KY" | "US-LA" | "US-ME" | "US-MD" | "US-MA" | "US-MI" | "US-MN" | "US-MS" | "US-MO" | "US-MT" | "US-NE" | "US-NV" | "US-NH" | "US-NJ" | "US-NM" | "US-NY" | "US-NC" | "US-ND" | "US-OH" | "US-OK" | "US-OR" | "US-PA" | "US-RI" | "US-SC" | "US-SD" | "US-TN" | "US-TX" | "US-UT" | "US-VT" | "US-VA" | "US-WA" | "US-WV" | "US-WI" | "US-WY">;
  /** Date the law was evaluated at. */
  as_of: string;
  /** Version of the check implementations. */
  rules_version: string;
  /** Version of the legal catalog. */
  catalog_version: string;
  /** sha256 of the canonical legal catalog. */
  catalog_hash: string;
  /** Not legal advice. */
  disclaimer: string;
  next_action: NextAction;
  /** User-facing roll-up: needs_fix > your_call > incomplete > compliant (every required check passes; pending live checks count as passing). `verdict` keeps the machine value. */
  compliance_status: "needs_fix" | "your_call" | "incomplete" | "compliant" | "not_checked";
  compliance: ComplianceRollup;
  replacement: CheckReplacement;
}

/** A checkout disclosure to check before it ships. The plan fields (price, interval, cancel_url…) may also be nested under `terms` or `merchant`, as in the other checks. */
export interface DisclosureCheckParams {
  /** The disclosure shown next to the purchase button, exactly as rendered. */
  text: string;
  /** Brand shown to subscribers; used in generated text. */
  merchant_name?: string;
  /** Alias of merchant_name (the {{brand_name}} merge field). Send one of the two. */
  brand_name?: string;
  /** Plan / product name. */
  plan_name?: string;
  /** Recurring price in major units (19.99). Or give `amount` in minor units. */
  price?: number | string;
  /** Recurring price in minor units (1999 = $19.99), Stripe style. */
  amount?: number;
  /** Three-letter ISO currency (default usd). */
  currency?: string;
  /** Billing interval: day, week, month or year (required unless `site` gives the plan). */
  interval?: string;
  /** Number of intervals between charges (default 1). */
  interval_count?: number;
  /** Free-trial length in days (0 or absent = no trial). */
  trial_days?: number;
  /** Intro / first-period price in major units ("$34.50 for your first box, then $69 every 2 weeks"). Or give `intro_amount` in minor units. */
  intro_price?: number | string;
  /** Intro / first-period price in minor units. */
  intro_amount?: number;
  /** How many billing periods the intro price lasts (default 1). */
  intro_periods?: number;
  /** Intro discount as a percentage off the recurring price (a Stripe coupon's percent_off: 20 for "20% off your first month"). Lasts `intro_periods` billing periods. Give one of intro_price / intro_amount, intro_percent_off or intro_amount_off. */
  intro_percent_off?: number;
  /** Intro discount as an amount off in minor units (a Stripe coupon's amount_off: 200 for $2.00 off). Lasts `intro_periods` billing periods. */
  intro_amount_off?: number;
  /** https URL where subscribers cancel online (used in generated text; a {{cancel_url}} placeholder otherwise). */
  cancel_url?: string;
  /** When a cancellation takes effect (default period_end). */
  cancel_timing?: "period_end" | "immediately";
  /** Label of the purchase button (default "Subscribe", or "Start free trial" with a trial). */
  button_text?: string;
  /** Other text next to the button (order summary), if any. */
  order_summary?: string;
  /** Where you sell: "all" (default) or state codes ("US-CA", "CA", "US-NY"; "US-FED" is always included). */
  jurisdictions?: "all" | Array<string>;
  /** Where and how the disclosure is shown. */
  placement?: {
    /** The disclosure is shown before / above the purchase button (default true). */
    above_button?: boolean;
    /** The disclosure is on the same page as the payment form and button (default true). */
    same_page_as_payment?: boolean;
    /** Rendered font size of the disclosure (default 14). */
    font_size_px?: number;
    /** WCAG contrast ratio of the text against its background (default ≈14.7). */
    contrast_ratio?: number;
    /** The disclosure is bold / semibold. */
    bold?: boolean;
    /** The disclosure is set off in a bordered or shaded box. */
    boxed?: boolean;
    /** Font size of the surrounding body text (default 14). */
    body_font_size_px?: number;
  };
  /** The consent checkbox, if any. Omitted = no checkbox. */
  consent?: {
    /** A checkbox the customer must tick to agree to the renewal terms. */
    checkbox: boolean;
    /** The checkbox is ticked by default. */
    prechecked?: boolean;
    /** The checkbox label (default "I agree to the automatic renewal terms above."). */
    label?: string;
    /** The form cannot be submitted without ticking it (default true). */
    required?: boolean;
  };
  /** Evaluate the law as of this date (YYYY-MM-DD, default today). */
  as_of?: string;
  /** Round 23: a site of yours (site_…): the disclosure is judged against the plan it states among the site's plans (the connected Stripe Prices win over plans typed in setup), with the site's merchant name, cancellation URL and jurisdictions, as verifyTask judges it. Plan fields you send are replaced by the plan's. "none" judges only what you send. */
  site?: string;
  /** With a site: judge the disclosure against this plan (name or Stripe Price id). An unknown plan is refused with the list of plans. */
  plan?: string;
}

