/** Proof that a subscriber affirmatively consented to the exact automatic-renewal terms shown. */
export interface Consent {
  /** Unique identifier of the consent (cons_…). */
  id: string;
  /** String representing the object's type. Always "consent". */
  object: "consent";
  /** true for live-mode objects, false for test mode (ck_test_ keys act on an isolated sandbox). */
  livemode: boolean;
  /** When Checkbox recorded the consent. Unix timestamp in seconds. */
  created: number;
  /** Site the consent belongs to. */
  site: string;
  /** What the subscriber saw. */
  disclosure: {
    /** disc_… when a server-issued disclosure was shown. */
    id: string | null;
    /** Disclosure text shown. */
    text: string;
    /** Consent checkbox label shown. */
    consent_label: string;
    /** sha256 of the disclosure text. */
    sha256: string;
    /** sha256 of disclosure + "\n" + consent label (the hash Fixes uses). */
    texts_sha256: string;
    /** The texts equal Checkbox's locked wording for the terms (or the disclosure's). */
    matches_locked_text: boolean;
  };
  /** Terms the disclosure states (DisclosureTerms). */
  terms: Record<string, unknown>;
  /** Checkbox state. */
  checkbox: {
    /** Always true. */
    checked: boolean;
    /** The box was pre-ticked (consent then is not affirmative). */
    initially_checked: boolean;
    /** Ticking was required. */
    required: boolean;
  };
  /** Page of the consent. */
  page_url: string | null;
  /** Origin of the browser request (null for server-recorded consents). */
  origin: string | null;
  /** sha256 of the browser User-Agent header. */
  user_agent_sha256: string | null;
  /** Your subscriber reference (set once, by a secret key only: createConsent from your server or updateConsent). Browser-recorded consents start with null. */
  customer_reference: string | null;
  /** Reference the page sent with a publishable key (customer-reference attribute). Unverified: anyone holding the public key can send any value, so bind the real subscription with updateConsent from your server. */
  client_reference: string | null;
  /** elements: recorded by the browser element; api: by your server. */
  source: "elements" | "api";
  /** elements.js version. */
  element_version: string | null;
  /** Device time (unix seconds). */
  client_timestamp: number | null;
  /** On-screen measurement summary (null for server-recorded consents). */
  presentation: {
    /** Guard-rail issues measured on screen. */
    violations: Array<string>;
    /** Safe styles replaced the theme. */
    fallback_applied: boolean;
    /** Font size. */
    font_size_px: number | null;
    /** Contrast ratio. */
    contrast_ratio: number | null;
    /** Above the pay button. */
    above_submit: boolean | null;
    /** Gap to the pay button. */
    gap_px: number | null;
    /** Set off by a border. */
    boxed: boolean;
    /** Visible. */
    visible: boolean;
  } | null;
  /** Your key/value pairs. */
  metadata: Record<string, string>;
  /** rcpt_… consent receipt recorded with this consent (what the subscriber saw), when the element sent one. */
  receipt?: string | null;
  /** Tamper-evident evidence record (verify with verifyEvidenceChain). */
  evidence: {
    /** ev_… of the evidence record holding the full consent document. */
    id: string | null;
    /** sha256 of the evidence document. */
    sha256: string | null;
    /** Position in the site's hash chain. */
    chain_hash: string | null;
  };
  /** Page capture fed to the compliance evaluation from this consent, when a new one was stored. */
  corroborating_capture?: string | null;
  next_action: NextAction;
}

/** What <checkbox-disclosure> measured on screen (sent by the element). */
