/** Result of re-checking a receipt's hash, signature and evidence chain. */
export interface ReceiptVerification {
  /** String representing the object's type. Always "receipt_verification". */
  object: "receipt_verification";
  /** Unique identifier of the receipt (rcpt_…). */
  receipt: string;
  /** Every check passed. */
  verified: boolean;
  /** Individual checks. */
  checks: {
    /** Content hash. */
    content: {
      /** The stored receipt hashes to receipt_sha256. */
      ok: boolean;
      /** Detail. */
      message: string;
    };
    /** Signature. */
    signature: {
      /** Checkbox's Ed25519 signature over the receipt hash verifies. */
      ok: boolean;
      /** Detail. */
      message: string;
    };
    /** Hash chain. */
    chain: {
      /** The site's evidence chain (which includes the receipt) verifies end to end. */
      ok: boolean;
      /** Detail. */
      message: string;
    };
    /** Shown values vs. the signed document. */
    index: {
      /** What this API, the dashboard, the image and the bundle show (binding, source, text, snapshot, flags, identifiers) matches the signed document. */
      ok: boolean;
      /** Detail (index_mismatch names the fields that differ). */
      message: string;
      /** Identifiers attached after signing (e.g. checkout_session once Stripe confirmed the checkout): not covered by the signature. */
      linked_after_signing: Array<string>;
    };
  };
  /** The receipt hash that was checked. */
  receipt_sha256: string;
  /** When the check ran. Unix timestamp in seconds. */
  verified_at: number;
  /** How to verify without Checkbox: download exportReceipt and run its verify.mjs. */
  offline: string;
}

