/** How to fix a failing check. */
export type TestRunRemediation = {
  /** What the law requires and what to change. */
  summary: string;
  /** Steps to fix it. */
  steps: Array<string>;
  /** Suggested copy that passes the checks, when there is one. */
  suggested_copy: string | null;
  /** Code that applies the fix, when there is one. */
  snippet: {
    /** Language of the code. */
    language: string;
    /** Code that applies the fix. */
    code: string;
  } | null;
} | null;

/** An agent-readable fix: what to change, where, and how to verify (run again). */
